package com.hbm.client.custommachine;
import com.hbm.client.gui.LegacyContainerScreen;
import com.hbm.fluid.FluidTank;
import com.hbm.item.fluid.client.FluidInfo;
import com.hbm.machine.custommachine.*;
import com.hbm.pneumatic.PatternMatcher;
import com.mojang.blaze3d.systems.RenderSystem;
import com.mojang.blaze3d.vertex.*;
import java.util.*;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.renderer.GameRenderer;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
/** Original176x256 atlas, split progress arrow, unused-lane covers and true smooth heat needle. */
public final class CustomMachineScreen extends LegacyContainerScreen<CustomMachineMenu> {
 public CustomMachineScreen(CustomMachineMenu menu,Inventory inventory,Component title){super(menu,inventory,title,ResourceLocation.parse("hbm:textures/gui/processing/gui_custom.png"),176,256);}
 @Override protected void renderLabels(GuiGraphics g,int mx,int my){var m=menu.machine;String translated=m.config.translation(CustomMachineContent.LANGUAGE.get());String name=translated==null?m.getName().getString():translated;g.drawString(font,name,68-font.width(name)/2,6,4210752,false);g.drawString(font,playerInventoryTitle,8,162,4210752,false);if(m.config.fluxMode)g.drawString(font,Component.translatable("gui.hbm.custom_machine.flux",m.flux),83,57,0x08ff00,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int mx,int my){super.renderBg(g,partial,mx,my);var m=menu.machine;var c=m.config;if(c.fluxMode)drawLegacyRegion(g,78,54,192,122,51,15);if(m.maxHeat>0){drawLegacyRegion(g,61,53,236,0,18,18);needle(g,(double)m.heat/c.maxHeat);}int progress=m.progress*90/m.maxProgress;drawLegacyRegion(g,78,119,192,0,Math.min(progress,44),16);if(progress>44)drawLegacyRegion(g,122,119,192,16,progress-44,16);int power=m.power.multiply(java.math.BigInteger.valueOf(52)).divide(c.maxPower).intValue();drawLegacyRegion(g,150,70-power,176,52-power,16,power);for(int row=0;row<2;row++)for(int col=0;col<3;col++){int i=row*3+col;if(c.itemInCount<=i){drawLegacyRegion(g,7+18*col,71+18*row,192+18*col,86+18*row,18,18);drawLegacyRegion(g,7+18*col,107+18*row,192+18*col,86+18*row,18,18);}if(c.itemOutCount<=i)drawLegacyRegion(g,77+18*col,71+18*row,192+18*col,86+18*row,18,18);}for(int i=0;i<3;i++){if(c.fluidInCount<=i)drawLegacyRegion(g,7+18*i,17,192+18*i,32,18,54);if(c.fluidOutCount<=i)drawLegacyRegion(g,77+18*i,17,192+18*i,32,18,36);}for(int i=0;i<m.inputTanks.length;i++)tank(g,m.inputTanks[i],8+18*i);for(int i=0;i<m.outputTanks.length;i++)tank(g,m.outputTanks[i],78+18*i);}
 private void tank(GuiGraphics g,FluidTank tank,int x){int height=tank.getMaxFill()==0?0:tank.getFill()*34/tank.getMaxFill();if(height<=0)return;int tint=tank.getTankType().getTint();g.setColor((tint>>16&255)/255F,(tint>>8&255)/255F,(tint&255)/255F,1);for(int offset=0;offset<height;){int length=Math.min(16,height-offset);g.blit(tank.getTankType().getTexture(),leftPos+x,topPos+52-offset-length,0,16-length,16,length,16,16);offset+=length;}g.setColor(1,1,1,1);}
 private void needle(GuiGraphics g,double ratio){float angle=(float)Math.toRadians(-Math.max(0,Math.min(1,ratio))*270-45);g.flush();RenderSystem.setShader(GameRenderer::getPositionColorShader);var out=Tesselator.getInstance().begin(VertexFormat.Mode.TRIANGLES,DefaultVertexFormat.POSITION_COLOR);for(float scale:new float[]{1.5F,1F}){int color=scale==1?0xff7f0000:0xff000000;for(float[] point:new float[][]{{0,5},{1,-2},{-1,-2}}){float x=(point[0]*(float)Math.cos(angle)-point[1]*(float)Math.sin(angle))*scale,y=(point[0]*(float)Math.sin(angle)+point[1]*(float)Math.cos(angle))*scale;out.addVertex(g.pose().last().pose(),leftPos+70+x,topPos+62+y,0).setColor(color);}}BufferUploader.drawWithShader(out.buildOrThrow());}
 @Override public void render(GuiGraphics g,int mx,int my,float partial){super.render(g,mx,my,partial);var m=menu.machine;if(legacyInfoHovered(mx,my,150,18,16,52))g.renderTooltip(font,Component.literal(m.power+" / "+m.config.maxPower+" HE"),mx,my);if(m.config.maxHeat>0&&legacyInfoHovered(mx,my,61,53,18,18))g.renderTooltip(font,Component.translatable("gui.hbm.custom_machine.heat",String.format(Locale.US,"%,d",m.heat),String.format(Locale.US,"%,d",m.config.maxHeat)),mx,my);if(menu.getCarried().isEmpty())for(var slot:menu.slots){int index=slot.getContainerSlot();if(slot.container==m&&index>=10&&index<16&&isHovering(slot.x,slot.y,16,16,mx,my)&&m.matcher.modes[index-10]!=null)g.renderComponentTooltip(font,List.of(Component.translatable("gui.hbm.custom_machine.change_pattern").withStyle(ChatFormatting.RED),PatternMatcher.label(m.matcher.modes[index-10])),mx,my-30);}for(int i=0;i<m.inputTanks.length;i++)tooltip(g,m.inputTanks[i],8+18*i,mx,my);for(int i=0;i<m.outputTanks.length;i++)tooltip(g,m.outputTanks[i],78+18*i,mx,my);}
 private void tooltip(GuiGraphics g,FluidTank tank,int x,int mx,int my){if(!legacyInfoHovered(mx,my,x,18,16,34))return;var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+" / "+tank.getMaxFill()+" mB"));if(tank.getPressure()!=0)lines.add(Component.translatable("gui.hbm.chemical.pressure",tank.getPressure()));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,mx,my);}
}
